"use client"

import { useState } from "react"
import Header from "@/components/header"
import Footer from "@/components/footer"
import CheckoutSteps from "@/components/checkout-steps"
import AddressSection from "@/components/address-section"
import PaymentSection from "@/components/payment-section"
import CheckoutSummary from "@/components/checkout-summary"

export default function CheckoutPage() {
  const [currentStep, setCurrentStep] = useState(1)
  const [selectedAddressId, setSelectedAddressId] = useState<number | null>(1)

  const handleAddressSelect = (id: number) => {
    setSelectedAddressId(id)
  }

  const handleContinueToPayment = () => {
    if (selectedAddressId) {
      setCurrentStep(2)
      window.scrollTo({ top: 0, behavior: "smooth" })
    }
  }

  const handlePlaceOrder = () => {
    alert("Order Placed Successfully! (This is a demo)")
  }

  // Mock Cart Data
  const cartItems = [
    {
      id: 1,
      name: "Classic Building Blocks Set (100 Pieces)",
      price: 1299,
      quantity: 1,
      image: "🧱",
    },
    {
      id: 2,
      name: "Premium Colored Pencils (48pc)",
      price: 599,
      quantity: 2,
      image: "✏️",
    },
    {
      id: 3,
      name: "Wooden Puzzle - World Map",
      price: 899,
      quantity: 1,
      image: "🧩",
    },
  ]

  const [isGiftWrapped, setIsGiftWrapped] = useState(false)

  // Calculations
  const subtotal = cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0)
  const shipping = 0
  const discount = 0
  const giftWrapFee = isGiftWrapped ? 50 : 0
  const tax = Math.round(subtotal * 0.18)
  const total = subtotal + shipping - discount + tax + giftWrapFee

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <Header />

      <main className="flex-grow max-w-7xl mx-auto px-4 py-8 w-full">
        <h1 className="text-3xl font-bold mb-8 text-center">Checkout</h1>

        <CheckoutSteps currentStep={currentStep} />

        <div className="flex flex-col lg:flex-row gap-8">
          {/* Left Column - Steps */}
          <div className="flex-1">
            {currentStep === 1 && (
              <AddressSection
                onAddressSelect={handleAddressSelect}
                onContinue={handleContinueToPayment}
              />
            )}

            {currentStep === 2 && <PaymentSection onPlaceOrder={handlePlaceOrder} />}
          </div>

          {/* Right Column - Summary */}
          <div className="w-full lg:w-96 flex-shrink-0">
            <div className="sticky top-24">
              <CheckoutSummary
                items={cartItems}
                subtotal={subtotal}
                shipping={shipping}
                discount={discount}
                tax={tax}
                total={total}
                giftWrapFee={giftWrapFee}
                isGiftWrapped={isGiftWrapped}
                onGiftWrapToggle={() => setIsGiftWrapped(!isGiftWrapped)}
              />
            </div>
          </div>
        </div>
      </main>

      <Footer />
    </div>
  )
}
